mapper.select:
SELECT rel_path, status, content_hash, chunked_hash, indexed_at, tags
FROM kb_document
WHERE rel_path = #{path}

mapper.update:
UPDATE kb_document
SET status       = 'indexed',
    content_hash = #{contentHash},
    chunked_hash = #{contentHash},
    indexed_at   = #{indexedAt}
WHERE rel_path = #{path}
